def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != 0]

    # The colored clues are diagonal stripes. Choose which diagonal
    # orientation contains the long stripes.
    groups = []
    for use_sum in (True, False):
        lines = {}
        for r, c, color in cells:
            k = r + c if use_sum else c - r
            lines.setdefault(k, []).append(color)
        score = sum(len(v) ** 2 for v in lines.values())
        groups.append((score, use_sum, lines))

    _, use_sum, lines = max(groups, key=lambda x: x[0])
    clues = {}
    for k, colors in lines.items():
        # A stripe has one color; ignore an orientation if it mixes colors.
        if len(set(colors)) == 1:
            clues[k] = colors[0]

    # Find the shortest repeating diagonal-color sequence consistent
    # with the observed stripes.
    period = None
    residues = None
    for p in range(1, h + w + 1):
        trial = {}
        valid = True
        for k, color in clues.items():
            q = k % p
            if q in trial and trial[q] != color:
                valid = False
                break
            trial[q] = color
        if valid:
            period, residues = p, trial
            break

    if period is None:
        return [row[:] for row in grid]

    # Fill any unconstrained sequence positions by the nearest known phase.
    known = sorted(residues)
    seq = []
    for q in range(period):
        if q in residues:
            seq.append(residues[q])
            continue
        if not known:
            seq.append(0)
            continue
        prev = max((x for x in known if x < q), default=known[-1] - period)
        nxt = min((x for x in known if x > q), default=known[0] + period)
        if q - prev <= nxt - q:
            seq.append(residues[prev % period])
        else:
            seq.append(residues[nxt % period])

    if use_sum:
        return [[seq[(r + c) % period] for c in range(w)] for r in range(h)]
    return [[seq[(c - r) % period] for c in range(w)] for r in range(h)]
